"""Small persistent audit spool; no business action may precede its commit."""
import contextlib
import hashlib
import json
import os
from pathlib import Path
import sqlite3


class AuditUnavailable(RuntimeError):
    pass


class QueueFull(RuntimeError):
    pass


def _open(database):
    connection = None
    try:
        connection = sqlite3.connect(database, timeout=1)
        connection.execute('PRAGMA journal_mode=DELETE')
        connection.execute('PRAGMA synchronous=FULL')
        return connection
    except sqlite3.Error as error:
        if connection is not None:
            connection.close()
        raise AuditUnavailable('audit storage unavailable') from error


def initialize(database):
    path = Path(database)
    try:
        if not path.exists():
            descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            os.close(descriptor)
        with contextlib.closing(_open(database)) as connection:
            with connection:
                connection.execute('CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT, source_key TEXT UNIQUE NOT NULL, payload BLOB NOT NULL, digest TEXT NOT NULL, receiver_seq INTEGER)')
    except (sqlite3.Error, OSError) as error:
        raise AuditUnavailable('audit initialization unavailable') from error


def encode(record):
    keys = {'host', 'boot', 'event_id', 'actor', 'action', 'allowed', 'mono_ns', 'detail', 'risk'}
    if not isinstance(record, dict) or set(record) != keys:
        raise ValueError('complete source audit fields required')
    for key in ('host', 'boot', 'event_id', 'actor', 'action', 'detail'):
        if not isinstance(record[key], str) or (key != 'detail' and not record[key]):
            raise ValueError('nonempty source identity and action fields required')
    if record['risk'] not in ('critical', 'routine'):
        raise ValueError('explicit approved event risk class required')
    if type(record['allowed']) is not bool or type(record['mono_ns']) is not int or record['mono_ns'] < 0:
        raise ValueError('explicit decision and monotonic observation required')
    payload = json.dumps(record, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode('utf8')
    if len(payload) > 512:
        raise ValueError('declared bounded event payload exceeded')
    identity = json.dumps([record[key] for key in ('host', 'boot', 'event_id')], ensure_ascii=False, separators=(',', ':'))
    return identity, payload, hashlib.sha256(payload).hexdigest()


def admit_many(database, records, byte_limit):
    if type(byte_limit) is not int or byte_limit <= 0 or not 1 <= len(records) <= 32:
        raise ValueError('finite byte quota and bounded batch required')
    prepared = [encode(record) for record in records]
    try:
        with contextlib.closing(_open(database)) as connection:
            with connection:
                connection.execute('BEGIN IMMEDIATE')
                pending_bytes = connection.execute('SELECT COALESCE(SUM(length(payload)),0) FROM events WHERE receiver_seq IS NULL').fetchone()[0]
                result = []
                for identity, payload, digest in prepared:
                    existing = connection.execute('SELECT seq,digest FROM events WHERE source_key=?', (identity,)).fetchone()
                    if existing:
                        if existing[1] != digest:
                            raise ValueError('same source event cannot change its original content')
                        result.append(existing[0])
                        continue
                    if pending_bytes + len(payload) > byte_limit:
                        raise QueueFull('finite durable audit buffer exhausted before business action')
                    cursor = connection.execute('INSERT INTO events(source_key,payload,digest) VALUES(?,?,?)', (identity, payload, digest))
                    result.append(cursor.lastrowid)
                    pending_bytes += len(payload)
            return result
    except sqlite3.Error as error:
        raise AuditUnavailable('audit commit unavailable before business action') from error


def pending(database, limit=32):
    if type(limit) is not int or not 1 <= limit <= 32:
        raise ValueError('bounded resend batch required')
    try:
        with contextlib.closing(_open(database)) as connection:
            rows = connection.execute('SELECT seq,payload,digest FROM events WHERE receiver_seq IS NULL ORDER BY seq LIMIT ?', (limit,)).fetchall()
        return [{'seq': sequence, 'record': json.loads(payload), 'digest': digest} for sequence, payload, digest in rows]
    except sqlite3.Error as error:
        raise AuditUnavailable('audit backlog unavailable') from error


def acknowledge(database, receipt):
    required = {'host', 'boot', 'event_id', 'digest', 'receiver_seq'}
    if not isinstance(receipt, dict) or not required <= set(receipt):
        raise ValueError('actual complete receiver receipt required')
    if any(not isinstance(receipt[key], str) or not receipt[key] for key in ('host', 'boot', 'event_id', 'digest')):
        raise ValueError('typed original receipt identity required')
    if type(receipt['receiver_seq']) is not int or receipt['receiver_seq'] <= 0:
        raise ValueError('actual positive receiver sequence required')
    identity = json.dumps([receipt[key] for key in ('host', 'boot', 'event_id')], ensure_ascii=False, separators=(',', ':'))
    try:
        with contextlib.closing(_open(database)) as connection:
            with connection:
                row = connection.execute('SELECT digest,receiver_seq FROM events WHERE source_key=?', (identity,)).fetchone()
                if row is None or row[0] != receipt['digest'] or (row[1] is not None and row[1] != receipt['receiver_seq']):
                    raise ValueError('receipt must confirm the exact retained source event')
                connection.execute('UPDATE events SET receiver_seq=? WHERE source_key=?', (receipt['receiver_seq'], identity))
    except sqlite3.Error as error:
        raise AuditUnavailable('receiver acknowledgement could not be retained') from error

