import json
import ssl
import urllib.error
import urllib.request
from urllib.parse import urlsplit


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, response, code, message, headers, new_url):
        return None


def send_many(url, ca_file, certificate, private_key, rows, timeout=0.35):
    from collections import Counter
    if urlsplit(url).scheme != 'https' or not 1 <= len(rows) <= 32:
        raise ValueError('authenticated bounded fixture HTTPS batch required')
    context = ssl.create_default_context(cafile=ca_file)
    context.load_cert_chain(certificate, private_key)
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect(), urllib.request.HTTPSHandler(context=context))
    records = [row['record'] for row in rows]
    payload = json.dumps(records, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode('utf8')
    request = urllib.request.Request(url, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    try:
        with opener.open(request, timeout=timeout) as response:
            if response.status != 200:
                return None
            raw = response.read(32769)
    except (urllib.error.URLError, TimeoutError, OSError):
        return None
    if len(raw) > 32768:
        raise ValueError('bounded receiver confirmation required')
    receipts = json.loads(raw)
    if not isinstance(receipts, list) or len(receipts) != len(rows):
        raise ValueError('complete structured receiver receipts required')
    actual = []
    for receipt in receipts:
        if not isinstance(receipt, dict):
            raise ValueError('structured actual receipt required')
        if type(receipt.get('receiver_seq')) is not int or receipt['receiver_seq'] <= 0:
            raise ValueError('valid actual receiver sequence required')
        if any(not isinstance(receipt.get(key), str) or not receipt[key] for key in ('host', 'boot', 'event_id', 'digest')):
            raise ValueError('typed receiver source and digest required')
        actual.append(tuple(receipt[key] for key in ('host', 'boot', 'event_id', 'digest')))
    expected = [tuple(row['record'][key] for key in ('host', 'boot', 'event_id')) + (row['digest'],) for row in rows]
    if Counter(actual) != Counter(expected):
        raise ValueError('receiver must confirm the exact original event identities and digests')
    return receipts


def send(url, ca_file, certificate, private_key, record, digest, timeout=0.35):
    receipts = send_many(url, ca_file, certificate, private_key, [{'record': record, 'digest': digest}], timeout)
    return None if receipts is None else receipts[0]

