import contextlib
import json
from pathlib import Path
import sqlite3


def report(database, receipts, byte_limit):
    if type(byte_limit) is not int or byte_limit <= 0:
        raise ValueError('finite configured buffer capacity required')
    uri = Path(database).resolve().as_uri() + '?mode=ro'
    with contextlib.closing(sqlite3.connect(uri, uri=True)) as connection:
        rows = connection.execute('SELECT seq,source_key,payload,digest,receiver_seq FROM events ORDER BY seq').fetchall()
    confirmed = {}
    conflicts = []
    duplicates = 0
    for receipt in receipts:
        identity = json.dumps([receipt[key] for key in ('host', 'boot', 'event_id')], ensure_ascii=False, separators=(',', ':'))
        pair = receipt['digest'], receipt['receiver_seq']
        if identity in confirmed:
            duplicates += 1
            if confirmed[identity] != pair:
                conflicts.append(identity)
        else:
            confirmed[identity] = pair
    missing = []
    bad_acknowledgements = []
    pending_bytes = 0
    source_order = []
    for sequence, identity, payload, digest, acknowledged in rows:
        source_order.append({'source_seq': sequence, 'identity': json.loads(identity), 'digest': digest})
        if acknowledged is None:
            pending_bytes += len(payload)
        actual = confirmed.get(identity)
        if actual is None:
            missing.append(json.loads(identity))
        elif actual[0] != digest:
            conflicts.append(identity)
        if acknowledged is not None and actual != (digest, acknowledged):
            bad_acknowledgements.append(json.loads(identity))
    return {'source_order': source_order, 'missing': missing,
            'conflicts': sorted(set(conflicts)), 'bad_acknowledgements': bad_acknowledgements,
            'repeated_receipt_count': duplicates, 'pending_bytes': pending_bytes,
            'byte_limit': byte_limit, 'free_buffer_bytes': max(0, byte_limit - pending_bytes),
            'watermark': 'full' if pending_bytes >= byte_limit else 'high' if pending_bytes >= byte_limit // 2 else 'normal',
            'complete': not missing and not conflicts and not bad_acknowledgements and pending_bytes == 0}

